%NOISEADVECTION.M%advection of substance with a source and noise, s. hsiang %(smh2137@columbia.edu), aug, 2007timelimit = 30;ct = c;u = 1;for i = 1:timelimit;    dcdx = diff( [0, ct(i,:)] ); %need the zero for the BC        %we generate a new vector of noise that is 1 x 100, with a chi-squared    %distribution (1 degree of freedom)        noise = random('chi2',1,1,100);        %we now change this run by adding the noise term to dc/dt, normalizing    %by .01        DcDt = .05 * sourcelocation + .01 * noise - u * dcdx;    newc = ct(i,:) + DcDt;    ct = [ct; newc];end